int configure_usb_console(struct console *co, char *options) {
    int baud_rate = 0;
    int data_bits = 0;
    char parity = '\0';
    int flow_control = 0;
    char *token;

    token = strtok(options, ",");
    if (!token) {
        return -EINVAL;
    }

    baud_rate = atoi(token);

    token = strtok(NULL, ",");
    if (!token) {
        return -EINVAL;
    }

    data_bits = atoi(token);

    token = strtok(NULL, ",");
    if (!token) {
        return -EINVAL;
    }

    parity = *token;

    token = strtok(NULL, ",");
    if (!token) {
        return -EINVAL;
    }

    flow_control = atoi(token);

    struct usb_serial_port *port = get_usb_serial_port(co->index);
    if (!port) {
        printk(KERN_ERR "Failed to get USB serial port for console index %d\n", co->index);
        return -ENODEV;
    }

    if (!usb_serial_port_is_connected(port)) {
        printk(KERN_ERR "USB serial port is not connected\n");
        return -ENODEV;
    }

    if (usb_serial_port_open(port, co, NULL) < 0) {
        return -EIO;
    }

    struct usb_serial_port_settings settings;
    settings.baud_rate = baud_rate;
    settings.data_bits = data_bits;
    settings.parity = parity;
    settings.flow_control = flow_control;

    if (usb_serial_configure_port(port, &settings) < 0) {
        usb_serial_port_close(port);
        return -EIO;
    }

    port->is_console = true;
    co->data = port;

    return 0;
}

int usb_console_configure(struct console *co, char *options) {
    struct usb_serial *serial;
    struct termios tios;
    int baud, bits, ret;
    char parity;
    int flow_control;

    if (options == NULL) {
        return -EINVAL;
    }

    ret = sscanf(options, "%d %c %d %d", &baud, &parity, &bits, &flow_control);
    if (ret < 4) {
        log_error("Invalid options format for USB console\n");
        return -EINVAL;
    }

    serial = usb_serial_get(co->index);
    if (!serial) {
        log_error("Failed to get USB serial port for console index %d\n", co->index);
        return -ENODEV;
    }

    if (!usb_serial_is_connected(serial)) {
        log_error("USB serial port for console index %d is not connected\n", co->index);
        return -ENODEV;
    }

    ret = usb_serial_open(serial);
    if (ret < 0) {
        log_error("Failed to open USB serial port for console index %d\n", co->index);
        return ret;
    }

    memset(&tios, 0, sizeof(tios));
    cfmakeraw(&tios);

    switch (baud) {
        case 9600:
            tios.c_cflag |= B9600;
            break;
        case 19200:
            tios.c_cflag |= B19200;
            break;
        case 115200:
            tios.c_cflag |= B115200;
            break;
        default:
            log_error("Unsupported baud rate: %d\n", baud);
            usb_serial_close(serial);
            return -EINVAL;
    }

    if (bits == 7) {
        tios.c_cflag &= ~CS8;
        tios.c_cflag |= CS7;
    } else if (bits == 8) {
        tios.c_cflag &= ~CS7;
        tios.c_cflag |= CS8;
    } else {
        log_error("Unsupported data bits: %d\n", bits);
        usb_serial_close(serial);
        return -EINVAL;
    }

    if (parity == 'o' || parity == 'O') {
        tios.c_cflag |= PARENB | PARODD;
        tios.c_iflag |= INPCK;
    } else if (parity == 'e' || parity == 'E') {
        tios.c_cflag |= PARENB;
        tios.c_iflag |= INPCK;
    } else if (parity == 'n' || parity == 'N') {
        tios.c_cflag &= ~PARENB;
        tios.c_iflag &= ~INPCK;
    } else {
        log_error("Unsupported parity setting: %c\n", parity);
        usb_serial_close(serial);
        return -EINVAL;
    }

    if (flow_control == 1) {
        tios.c_cflag |= CRTSCTS;
    } else {
        tios.c_cflag &= ~CRTSCTS;
    }

    ret = tcsetattr(serial->fd, TCSAFLUSH, &tios);
    if (ret < 0) {
        log_error("Failed to set terminal attributes for USB serial port\n");
        usb_serial_close(serial);
        return ret;
    }

    serial->is_console = 1;
    co->serial = serial;

    return 0;
}

int configure_usb_console(struct console *co, char *options) {
    int baud_rate = 0;
    int data_bits = 0;
    char parity = '\0';
    int flow_control = 0;
    int ret;
    struct usb_serial *port;

    // Parse the options string for baud rate, data bits, parity, and flow control
    if (sscanf(options, "%d,%d,%c,%d", &baud_rate, &data_bits, &parity, &flow_control) != 4) {
        // Invalid options format
        return -EINVAL;
    }

    // Retrieve the USB serial port associated with the console index
    port = get_usb_serial_port(co->index);
    if (!port) {
        // USB serial port not found
        return -ENODEV;
    }

    // Check if the USB serial port is connected
    if (!port->is_connected) {
        // USB serial port not connected
        pr_err("USB serial port not connected\n");
        return -ENODEV;
    }

    // Open the USB serial port
    ret = open_usb_serial_port(port);
    if (ret < 0) {
        // Failed to open the USB serial port
        return ret;
    }

    // Configure terminal settings
    ret = configure_terminal_settings(port, baud_rate, data_bits, parity, flow_control);
    if (ret < 0) {
        // Failed to configure terminal settings
        close_usb_serial_port(port);
        return ret;
    }

    // Mark the port as a system console
    port->is_console = true;

    // Store the port in the console structure
    co->port = port;

    return 0;
}

